def has_tag(character, key):
    return key in character.get("tags", [])


def get_candidates(answers):
    characters = DATABASE["characters"]
    pool = [c for c in characters if all(
        value == "unknown" or has_tag(c, key) == (value == "yes")
        for key, value in answers.items()
    )]
    if pool:
        return pool

    # If the database has imperfect or incomplete traits, use closest matches.
    scored = []
    for character in characters:
        score = 0
        for key, value in answers.items():
            if value == "unknown":
                continue
            score += 1 if has_tag(character, key) == (value == "yes") else -2
        scored.append((score, character))
    best = max(score for score, _ in scored)
    return [c for score, c in scored if score >= best - 1]


def choose_question(candidates, answers, asked):
    available = [t for t in DATABASE["traits"]
                 if t["key"] not in answers and t["key"] not in asked]
    best_trait = None
    best_score = -1
    for trait in available:
        yes_count = sum(has_tag(c, trait["key"]) for c in candidates)
        no_count = len(candidates) - yes_count
        if yes_count == 0 or no_count == 0:
            continue
        p = yes_count / len(candidates)
        balance = 1 - abs(0.5 - p) * 2
        score = balance * math.log2(len(candidates) + 1)
        if score > best_score:
            best_score = score
            best_trait = trait
    return best_trait


def make_guess(candidates, answers):
    if not candidates:
        candidates = DATABASE["characters"]
    def score(character):
        result = 0
        for key, value in answers.items():
            if value == "unknown":
                continue
            result += 1 if has_tag(character, key) == (value == "yes") else -1
        return result
    return sorted(candidates, key=lambda c: (-score(c), c["name"].lower()))[0]


def ask_yes_no(question):
    while True:
        answer = input(f"{question} [y/n/d=don't know, b=back]: ").strip().lower()
        if answer in ("y", "yes"):
            return "yes"
        if answer in ("n", "no"):
            return "no"
        if answer in ("d", "don't know", "dont know", "unknown", "?"):
            return "unknown"
        if answer in ("b", "back"):
            return "back"
        print("Please enter y, n, d, or b.")


def play_game():
    answers = {}
    asked = []
    print("\nThink of a character or famous person. I'll try to guess it!")
    print("Answer y = yes, n = no, d = don't know. Type b to undo the last answer.\n")

    while len(asked) < 20:
        candidates = get_candidates(answers)
        if len(candidates) <= 1:
            break
        trait = choose_question(candidates, answers, asked)
        if trait is None:
            break
        answer = ask_yes_no(trait["question"])
        if answer == "back":
            if asked:
                last_key = asked.pop()
                answers.pop(last_key, None)
                print("Last answer undone.\n")
            else:
                print("There is no previous question to undo.\n")
            continue
        answers[trait["key"]] = answer
        asked.append(trait["key"])
        print(f"Possible characters remaining: {len(get_candidates(answers))}\n")

    candidates = get_candidates(answers)
    guess = make_guess(candidates, answers)
    print("\nMy guess is...")
    print(f"  {guess['name']} — {guess.get('universe', 'Unknown universe')}")
    response = ask_yes_no("Did I guess correctly?")
    if response == "yes":
        print("Great! I guessed your character. 😎")
    elif response == "no":
        print("I didn't get it this time. This version has a built-in database of "
              f"{len(DATABASE['characters'])} characters. Try another round!")
    else:
        print("No problem! Let's try another round.")


def browse_database():
    term = input("Search characters (leave blank to list first 30): ").strip().lower()
    matches = [c for c in DATABASE["characters"]
               if term in c["name"].lower() or term in c.get("universe", "").lower()]
    print(f"\nFound {len(matches)} character(s):")
    for character in matches[:100]:
        print(f"- {character['name']} ({character.get('universe', 'Unknown universe')})")
    if len(matches) > 100:
        print(f"...and {len(matches) - 100} more.")
    print()


def main():
    print("=" * 44)
    print("             GENIEGUESS")
    print("       Akinator-style Python game")
    print("=" * 44)
    print(f"Database: {len(DATABASE['characters'])} characters | {len(DATABASE['traits'])} traits")
    while True:
        print("\n1. Play\n2. Search character database\n3. Exit")
        choice = input("Choose an option: ").strip()
        if choice == "1":
            play_game()
        elif choice == "2":
            browse_database()
        elif choice == "3":
            print("Thanks for playing GenieGuess!")
            break
        else:
            print("Please choose 1, 2, or 3.")


if __name__ == "__main__":
    main()
